var arr=new System.Collections.Generic.List<object>(); foreach(var name in new[]{"ObstacleTilemap","GameplayTilemap"}){var go=UnityEngine.GameObject.Find(name);var tm=go.GetComponent<UnityEngine.Tilemaps.Tilemap>();var cells=new System.Collections.Generic.List<object>();foreach(var p in tm.cellBounds.allPositionsWithin){var t=tm.GetTile(p);if(t!=null)cells.Add(new{x=p.x,y=p.y,tile=t.name});}arr.Add(new{name,cells});}return arr;
